:root {
  --sky: #4a90d9;
  --cloud: #eaf4ff;
  --sun: #f5a623;
  --grass: #2e7d32;
  --text-dark: #1a2e3b;
  --text-muted: #6b8fa8;
  --white: #ffffff;
  --border: #b8d6ef;
}

article.kite-tag {
  background-color: var(--white);
  border: 2px solid var(--sky);
  border-radius: 16px;
  width: 300px;
  padding: 20px;
  margin: 40px auto;
}

.tag-header {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 12px;
}

.tag-icon {
  font-size: 28px;
  line-height: 1;
}

.tag-title {
  font-size: 22px;
  font-weight: 700;
  color: var(--sky);
  margin: 0;
}

.tag-divider {
  height: 3px;
  background-color: var(--cloud);
  border-radius: 2px;
  margin-bottom: 14px;
  border: 1px solid var(--border);
}

.tag-body {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4px 12px;
  margin-bottom: 16px;
}

.tag-label {
  font-size: 11px;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin: 0;
}

.tag-value {
  font-size: 14px;
  font-weight: 700;
  color: var(--text-dark);
  margin: 0 0 8px 0;
}

.tag-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.tag-badge {
  background-color: var(--grass);
  color: var(--white);
  font-size: 12px;
  font-weight: 700;
  padding: 4px 12px;
  border-radius: 20px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.tag-date {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-muted);
}
